- [ ] **Step 1: Replace placeholder test with test for exact-target accumulation**

Replace the entire contents of `tests/collect.test.js`:

```js
import { collect } from '../src/collect.js';

test('returns exactly target unique items, stopping as soon as target is reached', async () => {
  let call = 0;
  const rounds = [
    ['a', 'b', 'a'],  // round 1: 2 unique added (a, b); duplicate 'a' ignored
    ['b', 'c', 'd'],  // round 2: 2 new (c, d) → total 4; 'b' ignored
    ['e', 'f', 'g'],  // round 3: should never be called if target === 4
  ];
  const findCandidates = () => rounds[call++];

  const result = await collect(4, findCandidates);

  expect(result).toHaveLength(4);
  expect(new Set(result).size).toBe(4);  // all items are distinct
  expect(call).toBe(2);                  // stopped after round 2, not round 3
});
```

