- [ ] **Step 5: Implement `collect`**

Replace the entire contents of `src/collect.js`:

```js
export async function collect(target, findCandidates) {
  const seen = new Set();
  while (seen.size < target) {
    const before = seen.size;
    const candidates = await findCandidates();
    for (const item of candidates) seen.add(item);
    const added = seen.size - before;
    console.log(`Round complete: ${added} new item(s) added (${seen.size}/${target} unique)`);
  }
  return [...seen].slice(0, target);
}
```

